(@GOSSIP+1385,0,0,'What happened to your other tribesmen?',0,1,1,@GOSSIP+1444,0,0,0,'',0,0),
(@GOSSIP+1391,1,7,'As if! Today you\'ll draw your last breath!',0,1,1,0,0,0,0,'',0,0),
