(@GOSSIP+1420,0,7,'Er... that\'s how I found them.  I wanted to show the king that they were a threat!  Say Captain... I overheard Guard Fengus calling you a fat, useless gnoll lover!',0,1,1,0,0,0,0,'',0,0),
(@GOSSIP+1422,0,0,'By An’she and Mu’sha, yet what of Lo’sho?',0,1,1,@GOSSIP+1447,0,0,0,'',0,0),
(@GOSSIP+1423,0,0,'What can I do with these gifts?',0,1,1,@GOSSIP+1425,0,0,0,'',0,0),
(@GOSSIP+1423,1,0,'What are love tokens?',0,1,1,@GOSSIP+1424,0,0,0,'',0,0),
